  cycle_conf_calendar: "कैलेंडर पर आधारित अनुमान। पूर्वानुमान को सटीक करने के लिए अगले 3 दिन BBT और LH जोड़ें।",
  cycle_conf_bbt_only: "कैलेंडर और आपका BBT। भरोसा बढ़ाने के लिए LH स्ट्रिप जोड़ें।",
  cycle_conf_bbt_lh: "कैलेंडर + BBT + LH — भरोसा ज़्यादा है। शिखर पक्का करने के लिए ओव्यूलेशन के बाद तापमान बदलने का इंतज़ार है।",
