  cycleSettings_intro: "ये मान आपकी फ़र्टाइल विंडो और पीरियड के अनुमान तय करते हैं। अगर पक्का न हो, तो डिफ़ॉल्ट रहने दें — आप जो दर्ज करती हैं उससे Grandma आपका असली चक्र सीख लेती हैं।",
