  cycleSettings_footer: "अनुमान केवल अनुमान हैं — चिकित्सा सलाह या गर्भनिरोधक तरीका नहीं। प्रजनन से जुड़ी चिंता हो तो अपने डॉक्टर से बात करें।",
  disclaimer_medical: "grandma.app रिकॉर्ड रखने और जानकारी का एक साधन है। यह कोई चिकित्सा उपकरण नहीं है, किसी स्थिति का निदान, इलाज या रोकथाम नहीं करता, और पेशेवर सलाह की जगह नहीं लेता। चक्र और प्रजनन क्षमता के अनुमान गर्भनिरोधक तरीका नहीं हैं। सवाल या लक्षण हों तो किसी स्वास्थ्य विशेषज्ञ से बात करें। आपात स्थिति में स्थानीय आपातकालीन नंबर पर कॉल करें।",
  disclaimer_short: "केवल रिकॉर्ड और जानकारी के लिए — यह चिकित्सा उपकरण या गर्भनिरोधक तरीका नहीं है। किसी भी चिंता के लिए अपने डॉक्टर से बात करें।",

