  dataTrans_sectionCollect: "हम क्या इकट्ठा करते हैं और क्यों",
  dataTrans_healthTitle: "सेहत और चक्र का डेटा",
  dataTrans_healthBody: "पीरियड, लक्षण, प्रेग्नेंसी के हफ़्ते, वज़न और मूड — सिर्फ़ आपकी ट्रैकिंग, जानकारी और Grandma की सलाह के लिए। यह आपका ही रहता है।",
  dataTrans_childTitle: "बच्चों की जानकारी",
