  dataTrans_aiTitle: "Grandma से बातचीत",
  dataTrans_aiBody: "आपके सवाल Grandma को अच्छा जवाब देने का संदर्भ देते हैं। आप कभी भी AI में डेटा का इस्तेमाल बंद कर सकती हैं और अपनी चैट हिस्ट्री साफ़ कर सकती हैं।",
