  about_expertiseTitle: "विशेषज्ञता पर आधारित",
  about_expertiseBody: "Grandma की सलाह स्त्री-रोग विशेषज्ञ, दाई और बाल-रोग की जानकारी पर बनी है। यह देखभाल भरा साथ है — आपके अपने डॉक्टर का विकल्प नहीं।",
  about_privacyTitle: "प्राइवेसी सबसे पहले",
  about_privacyBody: "आपकी सेहत और परिवार का डेटा आपका है। देखिए, हम ठीक-ठीक क्या इकट्ठा करते हैं और क्यों।",
  about_privacyPolicy: "प्राइवेसी पॉलिसी",
