  about_copyright: "© 2026 grandma.app. प्यार से बनाया गया।",
  help_title: "मदद और अक्सर पूछे सवाल",
  help_subtitle: "हम आपके लिए यहीं हैं",
  help_searchPlaceholder: "आप क्या खोजना चाहेंगी?",
  help_noResults: "कोई जवाब नहीं मिला। दूसरे शब्द आज़माएं, या नीचे हमसे संपर्क करें।",
  help_stillStuck: "अब भी मदद चाहिए?",
  help_stillStuckBody: "जवाब नहीं मिला? हमारी टीम खुशी से मदद करेगी।",
  help_contactUs: "हमसे संपर्क करें",
  help_catStart: "शुरुआत करना",
  help_catAccount: "खाता और डेटा",
  help_catCare: "केयर सर्कल",
  help_catAi: "Grandma AI",
  help_catBilling: "सब्सक्रिप्शन और बिलिंग",
  help_catPrivacy: "प्राइवेसी",
  help_q_modes: "सफ़र के मोड क्या हैं?",
  help_a_modes: "grandma.app तुम्हारे पड़ाव के हिसाब से ढलता है: चक्र (अपना चक्र देखना या गर्भधारण की कोशिश), गर्भावस्था, बच्चे (0–5 साल) और रजोनिवृत्ति। हर सफ़र तुम्हारी होम स्क्रीन, दर्ज की जाने वाली चीज़ें और Grandma की सलाह बदल देता है।",
  help_q_switchMode: "मोड कैसे बदलूँ?",
  help_a_switchMode: "सेटिंग्स टैब खोलो और मेरा सफ़र में किसी सफ़र पर टैप करो। हर सफ़र का डेटा अलग रहता है, इसलिए बदलने पर कुछ नहीं खोता।",
  help_q_logging: "कुछ दर्ज कैसे करूँ?",
  help_a_logging: "होम स्क्रीन या कैलेंडर टैब से दर्ज करो — दिन चुनो और क्या लिखना है: पीरियड, लक्षण, मूड, नींद और भी बहुत कुछ। सब कुछ तुम्हारे कैलेंडर और नोट्स में दिखता है।",
  help_q_export: "अपना डेटा एक्सपोर्ट कैसे करूँ?",
  help_a_export: "सेटिंग्स → डेटा और प्राइवेसी → हमारे पास जो डेटा है → मेरा सारा डेटा एक्सपोर्ट करें में जाएं। आपको हमारे पास सहेजी हर चीज़ की पूरी मशीन-पठनीय JSON कॉपी मिलेगी।",
  help_q_delete: "अपना खाता कैसे हटाऊँ?",
  help_a_delete: "सेटिंग्स → खाता → खाता हटाएं। इससे आपका डेटा हमारे सिस्टम से हमेशा के लिए मिट जाता है और इसे वापस नहीं किया जा सकता।",
  help_q_password: "पासवर्ड कैसे बदलूँ?",
  help_a_password: "सेटिंग्स → खाता → पासवर्ड बदलें। अगर आपने Apple या Google से साइन इन किया है, तो अपना लॉगिन उसी के ज़रिए संभालें।",
  help_q_invite: "अपने केयर सर्कल को कैसे बुलाऊँ?",
  help_a_invite: "सेटिंग्स → केयर सर्कल → आमंत्रित करें। पार्टनर, आया या दादा-दादी को सुरक्षित लिंक भेजें। वे आपकी चुनी हुई अनुमतियों के साथ ही जुड़ते हैं।",
  help_q_permissions: "क्या मैं तय कर सकती हूँ कि देखभालकर्ता क्या देखें?",
  help_a_permissions: "हाँ। हर देखभालकर्ता की अनुमतियाँ आप तय करती हैं — लॉग, सेहत के रिकॉर्ड और बाकी चीज़ें कौन देख या जोड़ सकता है। पहुँच कभी भी बदलें या हटाएं।",
  help_q_grandma: "Grandma कौन है?",
  help_a_grandma: "Grandma आपकी AI साथी है, जो Claude से चलती है। वह आपके सफ़र के संदर्भ के साथ सवालों के जवाब देती है और दिन-रात अपनापन भरी, काम की सलाह देती है।",
  help_q_medical: "क्या Grandma की सलाह मेडिकल सलाह है?",
  help_a_medical: "नहीं। Grandma देखभाल भरी, जानकारी देने वाली सलाह देती है — निदान या इलाज नहीं। सेहत की किसी भी चिंता के लिए हमेशा अपने डॉक्टर, दाई या बाल-रोग विशेषज्ञ से मिलें।",
  help_q_premium: "Premium में क्या-क्या है?",
  help_a_premium: "Premium में अनलिमिटेड स्कैन और चैट, पूरी जानकारी और रिमाइंडर खुल जाते हैं। आप मासिक या सालाना सब्सक्राइब कर सकती हैं।",
  help_q_cancel: "Premium कैसे रद्द करूँ?",
  help_a_cancel: "अपने ऐप-स्टोर खाते की सेटिंग्स में कभी भी सब्सक्रिप्शन संभालें या रद्द करें। बिलिंग अवधि खत्म होने तक आपके Premium फ़ीचर चालू रहते हैं।",
  help_q_dataSafe: "क्या मेरा डेटा सुरक्षित है?",
  help_a_dataSafe: "हाँ। आपका डेटा ट्रांसफ़र और स्टोरेज, दोनों में एन्क्रिप्टेड है, और रो-लेवल सिक्योरिटी से सुरक्षित है, ताकि सिर्फ़ आप और आपका चुना केयर सर्कल ही इसे देख सकें।",
  help_q_sell: "क्या आप मेरा डेटा बेचते हैं?",
  help_a_sell: "कभी नहीं। हम आपका निजी डेटा नहीं बेचते, और आपकी निजी सेहत या बच्चे के डेटा से किसी तीसरे पक्ष के AI को कभी ट्रेन नहीं करते।",
