  guidelines_subtitle: "साझा करने की एक भली जगह",
  guidelines_intro: "grandma.app माता-पिता के लिए एक-दूसरे का ईमानदारी से साथ देने की जगह है। इसे सबके लिए सुरक्षित रखने के लिए हम आपसे कुछ आसान नियम मानने को कहते हैं।",
  guidelines_rule1Title: "नरमी और सम्मान रखें",
  guidelines_rule1Body: "यहाँ हर कोई अपने सफ़र पर है। परेशान करना, धमकाना, नफ़रत भरी बातें या निजी हमले नहीं।",
  guidelines_rule2Title: "प्राइवेसी का ध्यान रखें",
  guidelines_rule2Body: "दूसरों की निजी या सेहत की जानकारी साझा न करें। अपने परिवार के बारे में क्या बताएं, इस पर भी सोचकर चलें।",
  guidelines_rule3Title: "साथ दें, निदान नहीं",
  guidelines_rule3Body: "अपना अनुभव और हौसला दें — मेडिकल निर्देश नहीं। सेहत की चिंता हो तो हमेशा लोगों को उनके डॉक्टर के पास भेजें।",
  guidelines_rule4Title: "स्पैम या बिक्री नहीं",
  guidelines_rule4Body: "समुदाय को जुड़ाव के लिए रखें, प्रचार के लिए नहीं। मार्केटप्लेस की लिस्टिंग एक्सचेंज में हों, फ़ीड में नहीं।",
  guidelines_rule5Title: "इसे सुरक्षित रखें",
  guidelines_rule5Body: "ऐसा कोई कंटेंट नहीं जो खुद को नुकसान, बच्चों को खतरा या कुछ भी गैरक़ानूनी बढ़ावा दे। हम उसे हटा देते हैं और खाता निलंबित कर सकते हैं।",
  guidelines_sectionReport: "कुछ ग़लत दिखे तो",
  guidelines_reportBody: "किसी भी पोस्ट या संदेश को देर तक दबाएं, फिर उसे रिपोर्ट करें या उस व्यक्ति को ब्लॉक करें। रिपोर्ट निजी रहती हैं और हमारी टीम उन्हें देखती है। आपातकाल में हमेशा स्थानीय आपातकालीन सेवाओं से संपर्क करें।",
  guidelines_footer: "इन नियमों को तोड़ने पर कंटेंट हट सकता है या खाता निलंबित हो सकता है। इस समुदाय को सुरक्षित रखने के लिए धन्यवाद।",
