  sw2_leap19_name: "घटनाएँ",
  sw2_leap19_desc: "यह समझना कि काम एक क्रम में होते हैं",
  sw2_leap19_brain: "इस समय के आसपास बच्चे अक्सर दुनिया को एक धुंधली तस्वीर की जगह घटनाओं की कड़ी के रूप में देखने लगते हैं। हर काम की शुरुआत, बीच और अंत होता है। यह कारण और परिणाम सोचने की शुरुआत है, इसीलिए अचानक हर चीज़ दिलचस्प लग सकती है।",
  sw2_leap19_tip: "पीक-ए-बू जैसे आसान कारण-और-परिणाम वाले खेल खेलिए — बच्चा सीख रहा है कि घटनाओं के नतीजे पहले से सोचे जा सकते हैं।",
  sw2_leap19_ph0: "चिपका रहता है, नीचे रखते ही रोता है, नींद बिगड़ती है। एक साथ इतना कुछ नया होने से बच्चा थका हुआ महसूस कर सकता है।",
  sw2_leap19_ph1: "बच्चा अक्सर हर काम को उसके बाद होने वाली बात से जोड़ने में लगा रहता है — धकेलना, गिराना, ध्यान से देखना।",
  sw2_leap19_ph2: "जानबूझकर हाथ बढ़ाना शुरू होता है, और चीज़ों के बने रहने की शुरुआती समझ भी — बच्चा गिरी हुई चीज़ें ढूँढ़ता है।",
  sw2_leap19_sg0: "अलग होने की घबराहट बढ़ना",
  sw2_leap19_sg1: "बहुत चिपकना",
  sw2_leap19_sg2: "खिलौना गिरने पर रोना",
  sw2_leap19_sg3: "झपकी से मना करना",
  sw2_leap19_sg4: "हर समय साथ खेलना चाहना",
  sw2_leap19_sg5: "दिनचर्या बदलने पर चिढ़ना",
  sw2_leap19_sk0: "जानबूझकर हाथ बढ़ाकर पकड़ना",
  sw2_leap19_sk1: "खिलौने हिलाना और पटकना",
  sw2_leap19_sk2: "खेलों को पहचानना",
  sw2_leap19_sk3: "\"ऊपर\" और \"नीचे\" समझना",
  sw2_leap19_sk4: "चलती चीज़ों को आँखों से देखना",
  sw2_leap19_sk5: "अचानक चौंकाने पर हँसना",
  sw2_leap19_ac0: "पीक-ए-बू और छुपन-छुपाई",
  sw2_leap19_ac1: "गेंद को आगे-पीछे लुढ़काना",
  sw2_leap19_ac2: "आसान कारण-परिणाम वाले खिलौने (दबाओ = आवाज़)",
  sw2_leap19_ac3: "दिनचर्या को कदम-दर-कदम बोलकर बताइए",
  sw2_leap5_name: "बदलती संवेदनाएँ",
  sw2_leap5_desc: "शिशु इंद्रियों की एक समृद्ध दुनिया खोजता है",
  sw2_leap5_brain: "इस समय आपका शिशु इंद्रियों से कहीं ज़्यादा बारीकियाँ महसूस करने लग सकता है — साफ़ दृश्य, समृद्ध आवाज़ें, शरीर की नई अनुभूतियाँ। यह एक साथ बहुत और बहुत सुंदर लग सकता है।",
  sw2_leap5_ph0: "ज़्यादा रोना, चिपके रहना और बेचैन नींद आम है। शिशु बहुत सारी नई संवेदी जानकारी ले रहा हो सकता है।",
  sw2_leap5_ph1: "शिशु कई नए दृश्य और आवाज़ें ग्रहण कर रहा है। चिड़चिड़ापन शांत होने से पहले चरम पर पहुँच सकता है।",
  sw2_leap5_ph2: "नई संवेदी समझ खिलती है — आप लंबे समय तक जागने और जान-बूझकर देखने की आदत देखेंगे।",
  sw2_leap5_sg0: "सामान्य से ज़्यादा रोता है",
  sw2_leap5_sg1: "लगातार दूध पीना चाहता है",
  sw2_leap5_sg2: "शांत करना कठिन होता है",
  sw2_leap5_sg3: "पास रहना पसंद करता है",
  sw2_leap5_sg4: "आसानी से चौंक जाता है",
  sw2_leap5_sg5: "कपड़े उतारना पसंद नहीं करता",
  sw2_leap5_sk0: "रोशनी और आवाज़ पर प्रतिक्रिया देता है",
  sw2_leap5_sk1: "नज़रों से चीज़ों को ज़्यादा सहजता से फ़ॉलो करता है",
  sw2_leap5_sk2: "पहली सामाजिक मुस्कान",
  sw2_leap5_sk3: "जागने के पल बढ़ते हैं",
  sw2_leap5_sk4: "आपकी आवाज़ की ओर मुड़ता है",
  sw2_leap5_sk5: "गहरे कंट्रास्ट वाले पैटर्न पर ध्यान देता है",
  sw2_leap5_ac0: "शिशु को बाहर की ओर मुँह करके पकड़ें ताकि वह कमरा देखे",
  sw2_leap5_ac1: "काले-सफ़ेद गहरे कंट्रास्ट वाले कार्ड दिखाएँ",
  sw2_leap5_ac2: "आप जो भी करें, ज़ोर से बोलकर बताएँ",
  sw2_leap5_ac3: "शांत पलों में शिशु की हल्की मालिश करें",
  sw2_leap5_tip: "अभी त्वचा से त्वचा का संपर्क बहुत फ़ायदेमंद है। शिशु को बाँधकर रखना और हल्का झुलाना चिड़चिड़े दिनों को आसान कर सकता है।",
