  pregnancy_affirmationFallback_0: "आपका शरीर ठीक-ठीक जानता है कि क्या करना है। उस पर पूरा भरोसा रखें।",
  pregnancy_affirmationFallback_1: "आप अपने सोचे से कहीं ज़्यादा मज़बूत और अपने महसूस किए से कहीं ज़्यादा हिम्मती हैं।",
  pregnancy_affirmationFallback_2: "हर दिन आप एक चमत्कार को बढ़ा रही हैं। आप अद्भुत हैं।",
  pregnancy_affirmationFallback_3: "आज अपने साथ कोमल रहें। आप काफ़ी कर रही हैं।",
