  pregnancy_affirmationFallback_5: "आप इसी के लिए बनी हैं। आपकी सहज समझ बुद्धिमान है।",
  pregnancy_affirmationFallback_6: "आराम करना भी ज़रूरी है। खुद का ध्यान रखना, अपने शिशु का ध्यान रखना है।",
  pregnancy_affirmationFallback_7: "आपकी भावनाएँ जायज़ हैं। नई जान को बढ़ाना कठिन भी है और सुंदर भी।",
  pregnancy_affirmationFallback_8: "इस सफ़र में आप अकेली नहीं हैं। आपको सहारा और साथ मिला हुआ है।",
  pregnancy_affirmationFallback_9: "हर दर्द और हर बदलाव आपके शरीर का अद्भुत काम है।",
  pregnancy_affirmationFallback_10: "अपने शिशु के लिए आप जो प्यार महसूस करती हैं, वह सच्चा और शक्तिशाली है।",
  pregnancy_affirmationFallback_11: "आप ठीक वहीं हैं जहाँ आपको इस समय होना चाहिए।",
  pregnancy_affirmationFallback_12: "आपके शरीर ने शून्य से एक इंसान बनाया है। यह अद्भुत है।",
  pregnancy_affirmationFallback_13: "आपका शिशु आपकी आवाज़ सुनता है और उसमें सुकून पाता है।",
  pregnancy_affirmationFallback_14: "गहरी साँस लें। आप और आपका शिशु ठीक हैं।",
  pregnancy_affirmationFallback_15: "प्रक्रिया पर भरोसा रखें। आपका शरीर और आपका शिशु तालमेल में हैं।",
  pregnancy_affirmationFallback_16: "आपको परफ़ेक्ट होने की ज़रूरत नहीं — आपके शिशु को बस आप चाहिए।",
